// This repo's own pack for how the site gets built and shipped — where the
// release/CI plumbing comes from, and what happens to the steps in a change
// that only the owner can perform. Prose only: both rules are judgment calls
// made while planning a change, not shapes a check over repo state can see
// (the canon's own packs already check the plumbing once it is adopted).
//
// Seeded 2026-08-02 by the grow_with_claudinite growth-extract pass over
// PRs #12, #31, #39 and issues #38, #40.
export default {
  id: 'repo-mechanics',
  ruleRoutingGuidance: {
    belongs:
      "this repo's release/CI plumbing, the owner-only setup steps, and how work is recorded and delivered — issues, PRs, commit messages",
    excludes: 'site markup and copy — html and site-copy; session tooling traps — session-tooling',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  seededByDefault: false,
  worldRules: [],
  workRules: [],
};

// This repo's own pack for how a session's TOOLING behaves here — the traps that
// cost a working session a retry or a wrong answer to the owner, and that no file
// in the tree would have warned about. Prose only: every rule here is about what
// an agent does at runtime, which no check over repo state can observe.
//
// Seeded 2026-07-30 by the grow_with_claudinite conversation-extract pass over
// the captured adoption session; new rules arrive the same way.
export default {
  id: 'session-tooling',
  ruleRoutingGuidance: {
    belongs: 'traps in the session tooling itself — fetching remote content, discovering available tools',
    excludes: 'anything about this repo content — site markup is html, research is product-wiki',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  seededByDefault: false,
  worldRules: [],
  workRules: [],
};

// This repo's own pack for the site's user-facing copy — claims made on the
// marketing pages (privacy, disclosures, "what we do/don't do" statements)
// staying accurate to what the site actually does. Prose only: whether a claim
// still matches the shipped behavior is a judgment call, not something a check
// over markup or code shape can verify.
//
// Seeded 2026-08-01 by the grow_with_claudinite growth-extract pass over PR #20.
export default {
  id: 'site-copy',
  ruleRoutingGuidance: {
    belongs: 'user-facing claims on the site (privacy page, footer disclosures, "what we do" copy) staying true to shipped behavior',
    excludes: 'markup/accessibility mechanics — html; CI and deploy mechanics — github-actions',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  seededByDefault: false,
  worldRules: [],
  workRules: [],
};
